const body = $json.body ?? {};
const errors = [];
const allowedPlatforms = ["facebook", "instagram", "linkedin", "tiktok"];
const allowedPillars = ["education", "trust", "engagement", "conversion"];

function requirePositiveInteger(field, label) {
  const value = Number(body[field]);
  if (!Number.isInteger(value) || value < 1) errors.push(label + " must be a positive number");
  return value;
}

function optionalText(field) {
  return String(body[field] ?? "").trim();
}

function requireStringArray(field, label, allowedValues) {
  const value = Array.isArray(body[field]) ? body[field] : [];
  const normalizedValues = value.map((item) => String(item ?? "").trim().toLowerCase()).filter(Boolean);

  if (normalizedValues.length === 0) {
    errors.push(label + " is required");
    return [];
  }

  if (normalizedValues.some((item) => !allowedValues.includes(item))) {
    errors.push(label + " contains an invalid value");
  }

  return [...new Set(normalizedValues)];
}

const customerId = requirePositiveInteger("customer_id", "Customer ID");
const brandProfileId = requirePositiveInteger("brand_profile_id", "Brand profile ID");
const numberOfPosts = requirePositiveInteger("number_of_posts", "Number of posts");
const platforms = requireStringArray("platforms", "Platforms", allowedPlatforms);
const contentPillars = requireStringArray("content_pillars", "Content pillars", allowedPillars);
const campaign = optionalText("campaign");
const offer = optionalText("offer");
const callToAction = optionalText("call_to_action");

if (errors.length > 0) {
  return [{ json: { valid: false, response: { success: false, message: "Validation failed", error: errors.join("; ") } } }];
}

return [{
  json: {
    valid: true,
    body: {
      customer_id: customerId,
      brand_profile_id: brandProfileId,
      number_of_posts: numberOfPosts,
      platforms,
      content_pillars: contentPillars,
      campaign,
      offer,
      call_to_action: callToAction
    }
  }
}];

const body = $json.body;
const topicTemplates = {
  education: [
    "How to avoid common mistakes with {offer}",
    "A quick checklist for {campaign}",
    "What customers should know before choosing {offer}"
  ],
  trust: [
    "What a reliable {offer} process looks like",
    "Why consistency matters in {campaign}",
    "Questions to ask before committing to {offer}"
  ],
  engagement: [
    "What is your biggest challenge with {campaign}?",
    "Myth or fact about {offer}",
    "A fast opinion check for your audience"
  ],
  conversion: [
    "When it is time to take the next step on {offer}",
    "Who gets the best result from {offer}",
    "A simple offer invite for {campaign}"
  ]
};

const goals = {
  education: "build_trust",
  trust: "proof",
  engagement: "conversation",
  conversion: "generate_leads"
};

function fillTemplate(template, values) {
  return template.replace(/\{(\w+)\}/g, (_, key) => values[key] ?? "");
}

function buildHashtagSeed(input) {
  return String(input ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((word) => `#${word}`)
    .join(" ");
}

const campaign = body.campaign || "your campaign";
const offer = body.offer || "your offer";
const callToAction = body.call_to_action || "Send a message to learn more";
const count = body.number_of_posts;
const posts = [];

body.platforms.forEach((platform) => {
  for (let index = 0; index < count; index += 1) {
    const pillar = body.content_pillars[index % body.content_pillars.length];
    const templates = topicTemplates[pillar];
    const topic = fillTemplate(templates[index % templates.length], {
      campaign,
      offer
    });

    posts.push({
      platform,
      topic,
      content_pillar: pillar,
      goal: goals[pillar],
      caption: `Stub idea for ${platform}. Focus on ${campaign}. Offer: ${offer}. CTA: ${callToAction}.`,
      hashtags: [
        buildHashtagSeed(platform),
        buildHashtagSeed(campaign),
        buildHashtagSeed(offer)
      ].filter(Boolean).join(" ")
    });
  }
});

return [{ json: { success: true, posts } }];

const body = $json.body;

function parseJsonContent(content) {
  const raw = String(content ?? "").trim();
  const cleaned = raw.replace(/^```(?:json)?/i, "").replace(/```$/i, "").trim();
  try {
    return JSON.parse(cleaned);
  } catch {
    const start = cleaned.indexOf("{");
    const end = cleaned.lastIndexOf("}");
    if (start >= 0 && end > start) {
      return JSON.parse(cleaned.slice(start, end + 1));
    }
    throw new Error("Model did not return valid JSON");
  }
}

async function callDeepSeek(messages) {
  const apiKey = $env.DEEPSEEK_API_KEY;

  if (!apiKey) {
    throw new Error("Missing DEEPSEEK_API_KEY in n8n environment");
  }

  const data = await this.helpers.httpRequest({
    method: "POST",
    url: "https://api.deepseek.com/chat/completions",
    headers: {
      "Content-Type": "application/json",
      Authorization: "Bearer " + apiKey
    },
    body: {
      model: "deepseek-chat",
      temperature: 0.7,
      response_format: { type: "json_object" },
      messages
    },
    json: true
  });

  return data?.choices?.[0]?.message?.content;
}

function cleanText(value) {
  return String(value ?? "").trim();
}

function normalizePost(post, index) {
  const platform = body.platforms.includes(String(post.platform ?? "").toLowerCase())
    ? String(post.platform).toLowerCase()
    : body.platforms[index % body.platforms.length];
  const pillar = body.content_pillars.includes(String(post.content_pillar ?? "").toLowerCase())
    ? String(post.content_pillar).toLowerCase()
    : body.content_pillars[index % body.content_pillars.length];

  return {
    platform,
    topic: cleanText(post.topic) || `Content idea ${index + 1}`,
    content_pillar: pillar,
    goal: cleanText(post.goal) || "build_trust",
    caption: cleanText(post.caption),
    hashtags: cleanText(post.hashtags)
  };
}

try {
