          "Use only requested content_pillars",
          "Keep captions concise",
          "Hashtags must be a space-separated string"
        ]
      })
    }
  ]);

  const parsed = parseJsonContent(content);
  const posts = Array.isArray(parsed.posts) ? parsed.posts.slice(0, totalPosts).map(normalizePost) : [];

  if (posts.length === 0) {
    throw new Error("DeepSeek returned no posts");
  }

  return [{ json: { success: true, posts } }];
} catch (error) {
  return [{ json: { success: false, message: "AI generation failed", error: error instanceof Error ? error.message : String(error) } }];
