const post = $json;
const body = $('Validate Input').item.json.body;
const actionConfig = {
  approve: {
    allowedStatuses: ["needs_review"],
    nextStatus: "approved",
    eventType: "approve_post",
    message: "Post approved successfully",
    errorMessage: ""
  },
  reject: {
    allowedStatuses: ["needs_review"],
    nextStatus: "cancelled",
    eventType: "reject_post",
    message: "Post rejected successfully",
    errorMessage: "Rejected in approval workflow"
  },
  cancel: {
    allowedStatuses: ["draft", "needs_review", "approved", "scheduled"],
    nextStatus: "cancelled",
    eventType: "cancel_post",
    message: "Post cancelled successfully",
    errorMessage: "Cancelled in approval workflow"
  }
};

const config = actionConfig[body.action];
const previousStatus = String(post.status ?? "").trim();

if (!config.allowedStatuses.includes(previousStatus)) {
  return [{
    json: {
      valid_transition: false,
      response: {
        success: false,
        message: "Invalid status transition",
        error: `Cannot ${body.action} a post with status ${previousStatus}`
      }
    }
  }];
}

return [{
  json: {
    valid_transition: true,
    body: {
      id: body.id,
      action: body.action,
      previous_status: previousStatus,
      next_status: config.nextStatus,
      event_type: config.eventType,
      message: config.message,
      error_message: config.errorMessage
    }
  }
}];
